      "javascript": "const fs = require('fs');\n\nclass ListNode {\n  constructor(val = 0, next = null) { this.val = val; this.next = next; }\n}\nclass TreeNode {\n  constructor(val = 0, left = null, right = null) { this.val = val; this.left = left; this.right = right; }\n}\nfunction buildList(vals) {\n  if (!vals.length) return null;\n  const head = new ListNode(vals[0]);\n  let cur = head;\n  for (let i = 1; i < vals.length; i++) { cur.next = new ListNode(vals[i]); cur = cur.next; }\n  return head;\n}\nfunction buildTree(tokens) {\n  if (!tokens.length || tokens[0] === 'null') return null;\n  const root = new TreeNode(parseInt(tokens[0], 10));\n  const queue = [root];\n  let i = 1;\n  while (queue.length && i < tokens.length) {\n    const node = queue.shift();\n    if (i < tokens.length && tokens[i] !== 'null') { node.left = new TreeNode(parseInt(tokens[i], 10)); queue.push(node.left); }\n    i++;\n    if (i < tokens.length && tokens[i] !== 'null') { node.right = new TreeNode(parseInt(tokens[i], 10)); queue.push(node.right); }\n    i++;\n  }\n  return root;\n}\nfunction fmt(x) {\n  if (x === null || x === undefined) return '';\n  if (typeof x === 'boolean') return x ? 'true' : 'false';\n  if (x instanceof TreeNode) {\n    const out = [];\n    const queue = [x];\n    while (queue.length) {\n      const node = queue.shift();\n      if (node === null) out.push('null');\n      else { out.push(String(node.val)); queue.push(node.left); queue.push(node.right); }\n    }\n    while (out.length && out[out.length - 1] === 'null') out.pop();\n    return out.join(' ');\n  }\n  if (x instanceof ListNode) {\n    const vals = [];\n    let cur = x;\n    while (cur) { vals.push(String(cur.val)); cur = cur.next; }\n    return vals.join(' ');\n  }\n  if (Array.isArray(x)) {\n    if (!x.length) return '';\n    if (Array.isArray(x[0])) {\n      return x.map(function (r) {\n        if (!r.length) return '';\n        if (typeof r[0] === 'string' && r[0].length === 1) return r.join('');\n        return r.map(String).join(' ');\n      }).join('\\n');\n    }\n    return x.map(String).join(' ');\n  }\n  return String(x);\n}\n\nfunction solve(nums) {\n  const out = [];\n  function backtrack(cur, used) {\n    if (cur.length === nums.length) { out.push(cur.slice()); return; }\n    for (let i = 0; i < nums.length; i++) {\n      if (used[i]) continue;\n      used[i] = true;\n      cur.push(nums[i]);\n      backtrack(cur, used);\n      cur.pop();\n      used[i] = false;\n    }\n  }\n  backtrack([], new Array(nums.length).fill(false));\n  return out;\n}\n\nconst data = fs.readFileSync(0, 'utf-8').trim().split(/\\s+/).filter(function (x) { return x !== ''; });\nif (data.length) {\n  const n = parseInt(data[0], 10); const nums = data.slice(1, 1 + n).map(Number);\n  console.log(fmt(solve(nums)));\n}\n"
